ee:message.ee:set-payload:
%dw 2.0
output application/json
var result = payload.ValidarIdentificacionResult

---
{
  "WSResponseScoring": {
    "WSResponseHeader": {
      "System_correlationID": correlationId,
      "Service": {
        "status": if (result.EstadoHomologado != "VIGENTE") "FAIL" else "PASS" 
      }
    },
    "GestionClientes": {
      "head": {
        "Interfaz": vars.originalPayload.Body.GestionClientes.head.Interfaz default "",
        "Destino": vars.originalPayload.Body.GestionClientes.head.Destino default "",
        "Respuesta": {
          "CodigoRespuesta": result.EstadoHomologado default "",
          "FechaRespuesta": now(),
          "CodigoError": if (!isEmpty(result.EstadoHomologado)) "0" else "-1",
          "DescripcionError": result.ResultadoProceso
        },
        "CodigoIntegracion": correlationId
      },
      "body": {
        "Cliente": {
          "TipoDocumento": vars.originalPayload.Body.GestionClientes.body.Cliente.TipoDocumento,
          "NumeroDocumento": vars.originalPayload.Body.GestionClientes.body.Cliente.NumeroDocumento,
          "EstadoDocumento": result.EstadoHomologado,
          "FechaExpedicionDocumento": vars.originalPayload.Body.GestionClientes.body.Cliente.FechaExpedicionDocumento as DateTime as String {format: "dd/MM/yyyy"},
          "DepartamentoExpedicionDocumento": vars.originalPayload.Properties.DEPARTAMENTO,
          "Nombres": vars.originalPayload.Properties.NOMBRE,
          "PrimerApellido": vars.originalPayload.Body.GestionClientes.body.Cliente.PrimerApellido default "",
          "SegundoApellido": "",
          "Genero": "",
          "Ciudad": vars.originalPayload.Properties.CIUDAD default "",
          "MercadoCuenta": result.TieneScore,
          "Score": {
            "tipo": result.Oferta default "",
            "puntaje": result.Score default "",
            "clasificacion": result.FechaScore default ""
          }
        }
      }
    }
  }
}

%dw 2.0
output application/json
var result = payload.ValidarIdentificacionResult
var xmlCentral = read (payload.ValidarIdentificacionResult.XmlCentral, "application/xml")
---
{
  "WSResponseScoring": {
    "WSResponseHeader": {
      "System_correlationID": correlationId,
      "Service": {
        "status": if (result.EstadoHomologado != "VIGENTE") "FAIL" else "PASS" 
      }
    },
    "GestionClientes": {
      "head": {
        "Interfaz": vars.originalPayload.Body.GestionClientes.head.Interfaz default "",
        "Destino": vars.originalPayload.Body.GestionClientes.head.Destino default "",
        "Respuesta": {
          "CodigoRespuesta": result.EstadoHomologado default "",
          "FechaRespuesta": now(),
          "CodigoError": if (!isEmpty(result.EstadoHomologado)) "0" else "-1",
          "DescripcionError": if(upper(result.EstadoHomologado) == "NO VIGENTE") xmlCentral.CIFIN.Tercero.Estado else result.ResultadoProceso
        },
        "CodigoIntegracion": correlationId
      },
      "body": {
        "Cliente": {
          "TipoDocumento": if (isEmpty(xmlCentral.CIFIN.Tercero.TipoIdentificacion)) vars.originalPayload.Body.GestionClientes.body.Cliente.TipoDocumento else xmlCentral.CIFIN.Tercero.TipoIdentificacion default "",
          "NumeroDocumento": if (isEmpty(xmlCentral.CIFIN.Tercero.NumeroIdentificacion)) vars.originalPayload.Body.GestionClientes.body.Cliente.NumeroDocumento else xmlCentral.CIFIN.Tercero.NumeroIdentificacion default "",
          "EstadoDocumento": result.EstadoHomologado default "",
          "FechaExpedicionDocumento": vars.originalPayload.Body.GestionClientes.body.Cliente.FechaExpedicionDocumento as DateTime as String {format: "dd/MM/yyyy"},
          "DepartamentoExpedicionDocumento": xmlCentral.CIFIN.Tercero.CodigoDepartamento default "",
          "Nombres": if (isEmpty(xmlCentral.CIFIN.Tercero.Nombre1)) xmlCentral.CIFIN.Tercero.NombreTitular else trim((xmlCentral.CIFIN.Tercero.Nombre1 ++ ' ' ++ xmlCentral.CIFIN.Tercero.Nombre2)) default "",
          "PrimerApellido": vars.originalPayload.Body.GestionClientes.body.Cliente.PrimerApellido default "",
          "SegundoApellido": xmlCentral.CIFIN.Tercero.Apellido2 default "",
          "Genero": xmlCentral.CIFIN.Tercero.Genero default "",
          "Ciudad": xmlCentral.CIFIN.Tercero.LugarExpedicion default "",
          "MercadoCuenta": result.TieneScore,
          "Score": {
            "tipo": result.Oferta default "",
            "puntaje": result.Score default "",
            "clasificacion": result.FechaScore default ""
          }
        }
      }
    }
  }
}

%dw 2.0
output application/json
var tipoDocumento = vars.originalPayload.Body.GestionClientes.body.Cliente.TipoDocumento default ""
---
{
    Identificador_Peticion: correlationId,
    Tipo_Documento: tipoDocumento, 
    Numero_Identificacion: vars.originalPayload.Body.GestionClientes.body.Cliente.NumeroDocumento as Number default null,
    Numero_Conexion: "",
    Tipo_Transaccion: "Registro Log LISIM",
    Fecha_Inicio: now(), 
    Fecha_Fin: now(),
    Estado_Transaccion: "",
    Sistema_Origen: "MULESOFT",
    Atributos: [
      {
        name: "FECHA_CONSULTA",
        value: now() as DateTime{format: "dd/MM/yyyy"}
      },
      {
        name: "HORA_CONSULTA",
        value: now() as DateTime{format: "HH:mm"}
      },
      {
        name: "TIPO_IDENTIFICACION",
        value: if(tipoDocumento == "1") "CC" else if (tipoDocumento == "4") "CE" else " "
      },
      {
        name: "NUMERO_IDENTIFICACION",
        value: vars.originalPayload.Body.GestionClientes.body.Cliente.NumeroDocumento default ""
      },
      {
        name: "APELLIDO",
        value: vars.originalPayload.Properties.APELLIDO default ""
      },
      {
        name: "NOMBRE",
        value: vars.originalPayload.Properties.NOMBRE default ""
      },
      {
        name: "TRAMITE",
        value: vars.originalPayload.Properties.TRAMITE default ""
      },
      {
        name: "TIPO_CONSULTA",
        value: "VALIDACION DOCUMENTO LISIM"
      },
      {
        name: "USUARIO",
        value: vars.originalPayload.Properties.USUARIO default ""
      },
      {
        name: "CANAL",
        value: vars.originalPayload.Properties.CANAL default ""
      },
      {
        name: "PROVEEDOR",
        value: vars.originalPayload.Properties.PROVEEDOR default ""
      },
      {
        name: "CIUDAD",
        value: vars.originalPayload.Properties.CIUDAD default ""
      },
      {
        name: "DEPARTAMENTO",
        value: vars.originalPayload.Properties.DEPARTAMENTO default ""
      },
      {
        name: "ESTADO_ETB",
        value: "ERROR"
      },
      {
        name: "SISTEMA_ORIGEN",
        value: vars.originalPayload.Properties.SISTEMA_ORIGEN default ""
      },
      {
        name: "MENSAJE",
        value:  write(vars.bodyToWs, "application/xml"),
      },
      {
        name: "NIVEL_RIESGO",
        value:  ""
      },
      {
        name: "SCORE",
        value: ""
      },
      {
        name: "ID",
        value: correlationId,
      },
      {
        name: "MODELO",
        value: vars.originalPayload.Properties.MODELO default ""
      },
      {
        name: "PORTAL",
        value: vars.originalPayload.Properties.PORTAL default ""
      },
      {
        name: "NUMERO_CONTACTO",
        value: vars.originalPayload.Properties.NUMERO_CONTACTO default ""
      },
      {
        name: "TIPO",
        value: vars.originalPayload.Properties.TIPO default ""
      },
      {
        name: "ESTRATO",
        value: vars.originalPayload.Properties.ESTRATO default ""
      }
      ]
  }

